.ds-composer { display: flex; align-items: flex-end; gap: 12px; padding: 10px 16px; background: #0f1719; border-top: 1px solid #2b3733; font-family: Archivo, ui-sans-serif, system-ui, sans-serif; }
.ds-composer-input { flex: 1; min-width: 0; height: 44px; padding: 0 12px; border: 1px solid #2b3733; border-radius: 4px; background: #11191b; color: #f7f7f1; font: 13px/1.4 Archivo, ui-sans-serif, system-ui, sans-serif; }
.ds-composer-input::placeholder { color: #87958c; }
.ds-composer-input:focus-visible { outline: 2px solid #d99a2a; outline-offset: 1px; border-color: #6b5a37; }
.ds-composer .ds-btn-primary { height: 44px; padding: 0 16px; }

.ds-tier { display: grid; grid-template-columns: 18px minmax(0,1fr) auto; gap: 9px; align-items: start; width: 100%; padding: 9px 11px; border: 1px solid #c9cec4; border-radius: 4px; background: #f4f4ee; color: #171c19; text-align: left; font-family: Archivo, ui-sans-serif, system-ui, sans-serif; cursor: pointer; }
.ds-tier + .ds-tier { margin-top: 6px; }
.ds-tier.is-on { border-color: #2d4bcc; background: #dfe5ff; }
.ds-tier:focus-visible { outline: 2px solid #2d4bcc; outline-offset: 2px; }
.ds-tier-radio { width: 13px; height: 13px; margin-top: 2px; border: 1px solid #59645c; border-radius: 50%; background: transparent; }
.ds-tier.is-on .ds-tier-radio { border: 4px solid #2d4bcc; background: #f4f4ee; }
.ds-tier-name { display: block; font-size: 13px; font-weight: 600; line-height: 1.3; }
.ds-tier-desc { display: block; margin-top: 2px; font-family: "Courier Prime", ui-monospace, monospace; font-size: 11px; line-height: 1.45; color: #59645c; }
.ds-tier-flag { font-family: "Courier Prime", ui-monospace, monospace; font-size: 10px; color: #59645c; }

