.ds-gate { position: relative; display: grid; grid-template-columns: 30px minmax(0,1fr) auto; align-items: center; gap: 10px; padding: 11px 14px; background: #f2e7d1; border: 1px solid #d8bc83; border-top: 2px solid #d99a2a; border-radius: 4px; font-family: Archivo, ui-sans-serif, system-ui, sans-serif; color: #171c19; }
.ds-gate-mark { width: 30px; height: 30px; display: grid; place-items: center; border: 1px solid #d8bc83; border-radius: 4px; background: #f4f4ee; color: #7a4408; font-family: "Courier Prime", ui-monospace, monospace; font-size: 14px; }
.ds-gate-title { font-size: 13px; font-weight: 600; }
.ds-gate-file { margin-top: 2px; font-family: "Courier Prime", ui-monospace, monospace; font-size: 11px; color: #59645c; }
.ds-gate-actions { display: flex; align-items: center; gap: 6px; }
.ds-gate-actions .ds-btn { height: 29px; }

.ds-spine { list-style: none; margin: 0; padding: 0; font-family: Archivo, ui-sans-serif, system-ui, sans-serif; color: #171c19; }
.ds-spine-row { display: grid; grid-template-columns: 63px 24px minmax(0,1fr); position: relative; }
.ds-spine-time { padding: 15px 12px 0 0; text-align: right; font-family: "Courier Prime", ui-monospace, monospace; font-size: 12px; color: #59645c; }
.ds-spine-node { position: relative; display: flex; justify-content: center; padding-top: 17px; }
.ds-spine-node::before { content: ""; position: absolute; top: 0; bottom: 0; left: 50%; width: 1px; background: #9ea79d; transform: translateX(-.5px); }
.ds-spine-node i { position: relative; z-index: 1; width: 9px; height: 9px; border: 1px solid #59645c; border-radius: 50%; background: #e8eae2; }
.ds-spine-row.is-current .ds-spine-node i { border-color: #7a4408; background: #d99a2a; box-shadow: 0 0 0 3px #f2e7d1; }
.ds-spine-body { padding: 13px 0 15px; border-bottom: 1px solid #c9cec4; }
.ds-spine-label { font-family: "Courier Prime", ui-monospace, monospace; font-size: 11px; color: #59645c; }
.ds-spine-text { margin-top: 3px; font-size: 13px; line-height: 1.5; }

.ds-card { padding: 12px 13px; border: 1px solid #c9cec4; border-radius: 4px; background: #f4f4ee; color: #171c19; font-family: Archivo, ui-sans-serif, system-ui, sans-serif; }
.ds-card-title { font-family: "Source Serif 4", Georgia, serif; font-size: 19px; font-weight: 600; line-height: 1.2; letter-spacing: -0.015em; }
.ds-card-meta { margin-top: 5px; font-family: "Courier Prime", ui-monospace, monospace; font-size: 11px; color: #59645c; }

.ds-runchip { position: relative; width: 44px; height: 44px; display: grid; place-items: center; border: 1px solid #34423e; border-radius: 4px; background: #131f20; color: #d7ded7; font-family: "Courier Prime", ui-monospace, monospace; font-size: 11px; cursor: pointer; }
.ds-runchip:hover { border-color: #5a6c65; background: #172526; }
.ds-runchip:focus-visible { outline: 2px solid #2d4bcc; outline-offset: 2px; }
.ds-runchip.is-active { border-color: #f4f4ee; box-shadow: inset 3px 0 0 #2d4bcc; }
.ds-dot { position: absolute; top: 5px; right: 5px; width: 5px; height: 5px; border-radius: 50%; background: #d99a2a; }
